{
  "status": "STABLE",
  "core_findings": [
    "Sampled training separation is strong across all four datasets: mean margins are 4.3966–7.1219 and negative-over-positive rates are 1.30–4.56%. Electronics has the weakest separation, followed by Industrial_and_Scientific.",
    "Embedding concentration scores of 0.5047–0.5112 indicate mean pairwise cosine similarity near zero, providing no evidence of broad directional collapse. These scores do not measure recommendation diversity."
  ],
  "key_implications": [
    "The model usually ranks sampled training positives above negatives, with Electronics retaining the largest weak-margin fraction.",
    "STABLE applies only to these measured training diagnostics; validation HR@10, training dynamics, predictor parity and routing correctness remain unestablished."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:pos_neg_margin_p10": 0.9509,
      "Electronics:pos_neg_neg_beats_pos_rate": 0.0456,
      "Electronics:pos_neg_small_margin_rate": 0.0724,
      "Industrial_and_Scientific:pos_neg_neg_beats_pos_rate": 0.0342,
      "Electronics:embedding_collapse_score": 0.5112
    },
    "brief_metric_read": {
      "Electronics:pos_neg_margin_p10": "Lowest lower-tail margin across datasets; still positive.",
      "Electronics:pos_neg_neg_beats_pos_rate": "4.56% of valid sampled training positions rank the negative higher.",
      "Electronics:pos_neg_small_margin_rate": "7.24% have margins below 0.5, the largest observed fraction.",
      "Industrial_and_Scientific:pos_neg_neg_beats_pos_rate": "Second-highest sampled training ranking-error rate.",
      "Electronics:embedding_collapse_score": "Highest concentration score, corresponding to mean cosine similarity of approximately 0.0224."
    }
  }
